import{_ as e,C as l,c as t,o as r,j as i,b as a,a0 as n,a as s,w as o,G as d,a1 as k}from"./chunks/framework.DKRgXLPU.js";const g=JSON.parse('{"title":"Å være en god lagspiller","description":"","frontmatter":{},"headers":[],"relativePath":"no/education/team-player/index.md","filePath":"no/education/team-player/index.md"}');const u=e({name:"no/education/team-player/index.md"},[["render",function(e,g,u,m,p,h){const f=l("Mermaid");return r(),t("div",null,[g[1]||(g[1]=i("h1",{id:"a-være-en-god-lagspiller",tabindex:"-1"},[s("Å være en god lagspiller "),i("a",{class:"header-anchor",href:"#a-være-en-god-lagspiller","aria-label":'Permalink to "Å være en god lagspiller"'},"​")],-1)),g[2]||(g[2]=i("p",null,"Pétanque spilles ofte i lag – double (dublettes) eller triple (triplettes). Individuelle ferdigheter teller, men lagdynamikk kan avgjøre om du får resultater eller ikke. De beste lagene er ikke alltid de dyktigste – det er de som jobber best sammen.",-1)),g[3]||(g[3]=i("div",{class:"tip custom-block"},[i("p",{class:"custom-block-title"},"Den store ideen"),i("p",null,[i("strong",null,"De beste lagene er ikke alltid de dyktigste – det er de som jobber best sammen."),s(" Å være ydmyk, sulten og følelsesmessig smart gjør deg til en god lagkamerat.")])],-1)),(r(),a(k,null,{default:o(()=>[d(f,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFlott%20lagkamerat%5D%20--%3E%20B%5BYdmyk%5D%0A%20%20%20%20A%20--%3E%20C%5BSulten%5D%0A%20%20%20%20A%20--%3E%20D%5BSmart%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BLagets%20suksess%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20E%20--%3E%20F%5BMesterskapsytelse%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23e3f2fd%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20D%20fill%3A%23f3e5f5%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:o(()=>[...g[0]||(g[0]=[s(" Loading... ",-1)])]),_:1})),g[4]||(g[4]=n('<h2 id="hva-kjennetegner-en-god-lagkamerat" tabindex="-1">Hva kjennetegner en god lagkamerat? <a class="header-anchor" href="#hva-kjennetegner-en-god-lagkamerat" aria-label="Permalink to &quot;Hva kjennetegner en god lagkamerat?&quot;">​</a></h2><p>Forskning og erfaring peker på tre viktige egenskaper:</p><h3 id="_1-ydmyk" tabindex="-1">1. Ydmyk <a class="header-anchor" href="#_1-ydmyk" aria-label="Permalink to &quot;1. Ydmyk&quot;">​</a></h3><ul><li>Prioriterer lagets suksess fremfor personlig ære</li><li>Anerkjenner andres bidrag</li><li>Innrømmer feil uten unnskyldninger</li><li>Åpen for tilbakemeldinger og læring</li><li>Trenger ikke å være stjernen</li></ul><h3 id="_2-sulten" tabindex="-1">2. Sulten <a class="header-anchor" href="#_2-sulten" aria-label="Permalink to &quot;2. Sulten&quot;">​</a></h3><ul><li>Selvmotivert og drevet</li><li>Gjør jobben uten å bli spurt</li><li>Alltid på jakt etter forbedring</li><li>Gir energi til laget</li><li>Lønner ikke på talent</li></ul><h3 id="_3-smart-følelsesmessig" tabindex="-1">3. Smart (følelsesmessig) <a class="header-anchor" href="#_3-smart-følelsesmessig" aria-label="Permalink to &quot;3. Smart (følelsesmessig)&quot;">​</a></h3><ul><li>Leser situasjoner og mennesker godt</li><li>Vet når man skal snakke og når man skal lytte</li><li>Håndterer sine egne følelser</li><li>Støtter lagkamerater på riktig måte</li><li>Håndterer konflikter konstruktivt</li></ul><h2 id="grunnlaget-for-teamsuksess" tabindex="-1">Grunnlaget for teamsuksess <a class="header-anchor" href="#grunnlaget-for-teamsuksess" aria-label="Permalink to &quot;Grunnlaget for teamsuksess&quot;">​</a></h2><h3 id="felles-mal-og-visjon" tabindex="-1">Felles mål og visjon <a class="header-anchor" href="#felles-mal-og-visjon" aria-label="Permalink to &quot;Felles mål og visjon&quot;">​</a></h3><p>Sterke lag har:</p><ul><li>Tydelige, avtalte mål</li><li>Individuelle mål i samsvar med lagets mål</li><li>Felles forståelse av hva suksess ser ut som</li><li>Forpliktelse til det kollektive oppdraget</li></ul><p><strong>Spørsmål å diskutere med teamet ditt:</strong></p><ul><li>Hva prøver vi å oppnå sammen?</li><li>Hvordan ser suksess ut for oss?</li><li>Hvordan støtter våre individuelle mål laget?</li></ul><h3 id="effektiv-kommunikasjon" tabindex="-1">Effektiv kommunikasjon <a class="header-anchor" href="#effektiv-kommunikasjon" aria-label="Permalink to &quot;Effektiv kommunikasjon&quot;">​</a></h3><p>Kommunikasjon er livsnerven i teamets ytelse.</p><p><strong>God teamkommunikasjon:</strong></p><ul><li>Åpen og ærlig</li><li>Respektfull, selv i uenighet</li><li>Tydelig og spesifikk</li><li>Toveis (snakking OG lytting)</li><li>Rettidig (riktig informasjon til rett tid)</li></ul><p><strong>Under kampene:</strong></p><ul><li>Diskuter strategi før hver omgang</li><li>Del observasjoner om terreng, motstandere</li><li>Koordinere hvem som kaster når</li><li>Støtt hverandre etter kast (gode eller dårlige)</li></ul><h3 id="tillit-og-respekt" tabindex="-1">Tillit og respekt <a class="header-anchor" href="#tillit-og-respekt" aria-label="Permalink to &quot;Tillit og respekt&quot;">​</a></h3><p>Uten tillit faller lag fra hverandre under press.</p><p><strong>Bygge tillit:</strong></p><ul><li>Vær pålitelig (gjør det du sier)</li><li>Vær kompetent (gjør jobben din bra)</li><li>Vær ærlig (selv når det er vanskelig)</li><li>Vis sårbarhet (innrøm utfordringer)</li><li>Støtt andre konsekvent</li></ul><p><strong>Viser respekt:</strong></p><ul><li>Verdsett hver enkelt persons bidrag</li><li>Lytt til ulike perspektiver</li><li>Anerkjenn innsatsen, ikke bare resultatene</li><li>Betrakt alles rolle som viktig</li></ul><h3 id="tydelige-roller" tabindex="-1">Tydelige roller <a class="header-anchor" href="#tydelige-roller" aria-label="Permalink to &quot;Tydelige roller&quot;">​</a></h3><p>Alle burde forstå:</p><ul><li>Deres primære ansvarsområder</li><li>Hvordan de bidrar til teamet</li><li>Hva andre regner med dem for</li><li>Når man skal ta et skritt frem og når man skal ta et skritt tilbake</li></ul><p><strong>I trippel:</strong></p><table tabindex="0"><thead><tr><th>Rolle</th><th>Primærfokus</th><th>Nøkkelegenskaper</th></tr></thead><tbody><tr><td>Peker</td><td>Plasser boules i nærheten av knekt</td><td>Presisjon, konsistens</td></tr><tr><td>Midt</td><td>Tilpass deg situasjonen</td><td>Allsidighet, lesespill</td></tr><tr><td>Skytter</td><td>Fjern motstanderens kuler</td><td>Nøyaktighet under press</td></tr></tbody></table><p>Roller kan være fleksible, men klarhet hjelper.</p><h2 id="lagdynamikk-under-konkurransen" tabindex="-1">Lagdynamikk under konkurransen <a class="header-anchor" href="#lagdynamikk-under-konkurransen" aria-label="Permalink to &quot;Lagdynamikk under konkurransen&quot;">​</a></h2><h3 id="før-kampen" tabindex="-1">Før kampen <a class="header-anchor" href="#før-kampen" aria-label="Permalink to &quot;Før kampen&quot;">​</a></h3><ul><li>Kom sammen, varm opp sammen</li><li>Diskuter generell strategi</li><li>Sett tonen (positiv, fokusert)</li><li>Sjekk hvordan alle har det</li></ul><h3 id="under-spillet" tabindex="-1">Under spillet <a class="header-anchor" href="#under-spillet" aria-label="Permalink to &quot;Under spillet&quot;">​</a></h3><ul><li>Kommuniser mellom endene</li><li>Vær positiv uansett poengsum</li><li>Støtt hverandre etter feil</li><li>Feir suksesser sammen (kort)</li><li>Hold fokus på prosessen, ikke resultatet</li></ul><h3 id="etter-feil" tabindex="-1">Etter feil <a class="header-anchor" href="#etter-feil" aria-label="Permalink to &quot;Etter feil&quot;">​</a></h3><p>Hva du IKKE skal gjøre:</p><ul><li>Vis frustrasjon synlig</li><li>Kritisere eller skylde på</li><li>Trekk deg tilbake eller still deg</li><li>Dvel ved hva som skjedde</li></ul><p>Hva du skal gjøre:</p><ul><li>Rask bekreftelse (&quot;ingen problem&quot;)</li><li>Flytt fokus til neste kast</li><li>Oppretthold positivt kroppsspråk</li><li>Stol på at lagkameraten din kommer seg</li></ul><h3 id="etter-kampen" tabindex="-1">Etter kampen <a class="header-anchor" href="#etter-kampen" aria-label="Permalink to &quot;Etter kampen&quot;">​</a></h3><ul><li>Gjennomgå sammen (hva fungerte, hva fungerte ikke)</li><li>Anerkjenn individuelle bidrag</li><li>Diskuter forbedringer til neste gang</li><li>Oppretthold relasjoner uavhengig av resultat</li></ul><h2 id="kommunikasjonsmønstre" tabindex="-1">Kommunikasjonsmønstre <a class="header-anchor" href="#kommunikasjonsmønstre" aria-label="Permalink to &quot;Kommunikasjonsmønstre&quot;">​</a></h2><h3 id="konstruktiv-tilbakemelding" tabindex="-1">Konstruktiv tilbakemelding <a class="header-anchor" href="#konstruktiv-tilbakemelding" aria-label="Permalink to &quot;Konstruktiv tilbakemelding&quot;">​</a></h3><p><strong>Dårlig:</strong> «Du bommer stadig på de skuddene» <strong>Bedre:</strong> «Jeg la merke til at slagene går til venstre – vil du prøve å justere holdningen din?»</p><h3 id="støttende-respons-pa-feil" tabindex="-1">Støttende respons på feil <a class="header-anchor" href="#støttende-respons-pa-feil" aria-label="Permalink to &quot;Støttende respons på feil&quot;">​</a></h3><p><strong>Dårlig:</strong> <em>Stillhet eller synlig frustrasjon</em><strong>Bedre:</strong> «Vanskelig. Du har den neste.»</p><h3 id="strategisk-diskusjon" tabindex="-1">Strategisk diskusjon <a class="header-anchor" href="#strategisk-diskusjon" aria-label="Permalink to &quot;Strategisk diskusjon&quot;">​</a></h3><p><strong>Stakkars:</strong> «Bare skyt den» <strong>Bedre:</strong> «Hva synes du – å peke for å blokkere eller å prøve å skyte? Jeg ser fordeler og ulemper begge veier.»</p><h2 id="bygge-lagkultur" tabindex="-1">Bygge lagkultur <a class="header-anchor" href="#bygge-lagkultur" aria-label="Permalink to &quot;Bygge lagkultur&quot;">​</a></h2><p>Gode team utvikler seg delt:</p><ul><li><strong>Verdier:</strong> Hva vi står for</li><li><strong>Normer:</strong> Hvordan vi oppfører oss</li><li><strong>Språk:</strong> Hvordan vi kommuniserer</li><li><strong>Ritualer:</strong> Hva vi gjør sammen</li></ul><p><strong>Eksempler:</strong></p><ul><li>Håndhilse alltid før og etter</li><li>Spesifikke oppmuntrende fraser</li><li>Rutine sammen før kampen</li><li>Måltid eller drikke etter kampen</li></ul><h2 id="i-denne-delen" tabindex="-1">I denne delen <a class="header-anchor" href="#i-denne-delen" aria-label="Permalink to &quot;I denne delen&quot;">​</a></h2><ul><li><strong><a href="/no/utdanning/lagspiller/kommunikasjon">Teamkommunikasjon</a></strong> - Detaljert veiledning for effektiv kommunikasjon</li></ul><h2 id="viktig-konklusjon" tabindex="-1">Viktig konklusjon <a class="header-anchor" href="#viktig-konklusjon" aria-label="Permalink to &quot;Viktig konklusjon&quot;">​</a></h2><blockquote><p>Laget ditt er bare så sterkt som det svakeste forholdet, ikke den svakeste spilleren.</p></blockquote><p>Invester i lagkameratene dine. Bygg tillit. Kommuniser godt. Vinn sammen.</p>',61))])}]]);export{g as __pageData,u as default};
